{"I_AM_FRIENDLY","reg=club|st=neutral",{"Friendly's a start - Useful's better - which one are you?"},false,{[1]="GENERIC"}},
{"I_AM_FRIENDLY","role=crime_member|st=neutral|hour=20,5",{"Everybody's friendly at eight in the morning - come back at midnight and say it"}},
{"I_AM_FRIENDLY","role=mercenary|st=neutral",{"Friendly, hostile, whatever, I care who's paying - nobody is - so - hi"}},
{"I_AM_FRIENDLY","reg=worker|tmp=seasoned|st=neutral",{"Fine by me, I got a busted radiator and a bad attitude, and only one's fixable"}},
{"I_AM_FRIENDLY","reg=civilian,family|tmp=fresh|st=careful",{"Then stop right there, please, friendly can talk to me just fine from there"}},
